const fs = require('fs-extra');
const path = require('path');

const outputFileName = "LuaSystems.lua"

function gen(config, outputPath) {
    fs.ensureDirSync(outputPath);
    // clone config, reset each key to item's RbxPath
    const newConfig = {};
    for (const [key, item] of Object.entries(config)) {
        newConfig[item.RbxPath] = item;
    }
    config = newConfig;

    var json = JSON.stringify(config, null, 2)

    var text = `

local text = [[${json}]]

return game.HttpService:JSONDecode(text)

    `


    fs.writeFileSync(path.join(outputPath, outputFileName), text);
    console.log(`write file ${outputPath}`)
}


module.exports = gen;